#include <iostream>
using namespace std;

int main() {
    int n;

    cout << "Inserire un numero:" << endl;
    cin >> n;

    // Se il numero è dispari, decrementa di 1 per renderlo pari
    if (n % 2 != 0)
        n = n - 1;

    // Ciclo do-while per stampare i numeri pari in ordine decrescente
    do {
        cout << n << endl;
        n = n - 2;
    } while (n != 0);

    system("pause");
}
